BEGIN;
CREATE TABLE IF NOT EXISTS payer_fee_schedule (
    payer_key TEXT NOT NULL,
    category TEXT NOT NULL,
    code TEXT NOT NULL,
    description TEXT NOT NULL,
    allowed_cents INTEGER NOT NULL CHECK (allowed_cents > 0),
    source_reference TEXT NOT NULL,
    effective_from DATE NOT NULL,
    PRIMARY KEY (payer_key, category, code, effective_from)
);
ON CONFLICT (payer_key, category, code, effective_from) DO UPDATE SET
    description = EXCLUDED.description, allowed_cents = EXCLUDED.allowed_cents,
    source_reference = EXCLUDED.source_reference;
COMMIT;
